class Solution {
    public int longestPalindrome(String s) {
        Set<Character> unpaired = new HashSet<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (unpaired.contains(c)) {
                unpaired.remove(c);
            } else {
                unpaired.add(c);
            }
        }
        return unpaired.isEmpty() ? s.length() : s.length() - unpaired.size() + 1;
    }
}

