class Solution {
    public int longestPalindrome(String s) {
        int[] counts = new int[128];
        for (int i = 0; i < s.length(); i++) {
            counts[s.charAt(i)]++;
        }
        int length = 0;
        for (int c : counts) {
            length += (c / 2) * 2;
            if (length % 2 == 0 && c % 2 == 1) {
                length++;
            }
        }
        return length;
    }
}

