class Solution:
    def intToRoman(self, num: int) -> str:
        values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
        symbols = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
        parts = []
        for val, sym in zip(values, symbols):
            if num == 0:
                break
            count = num // val
            if count:
                parts.append(sym * count)
                num -= val * count
        return "".join(parts)

