class Solution:
    def multiply(self, num1: str, num2: str) -> str:
        if num1 == "0" or num2 == "0":
            return "0"
        m, n = len(num1), len(num2)
        pos = [0] * (m + n)
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                mul = (ord(num1[i]) - 48) * (ord(num2[j]) - 48)
                total = mul + pos[i + j + 1]
                pos[i + j + 1] = total % 10
                pos[i + j] += total // 10
        res = []
        skip = True
        for digit in pos:
            if skip and digit == 0:
                continue
            skip = False
            res.append(str(digit))
        return "".join(res)
